{
  "campaign_name": "Teste Mensagem Básica",
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{test_number}}",
      "vars": {
        "nome": "João Silva",
        "produto": "Smartphone Galaxy",
        "desconto": "20%"
      }
    }
  ],
  "content": {
    "text": {
      "message": "Olá {{nome}}! Seu {{produto}} está disponível com {{desconto}} de desconto. Aproveite!"
    }
  },
  "callback": "https://webhook.site/seu-webhook-aqui",
  "fallback": [
    {
      "channel": "SMS",
      "content": "Ola {{nome}}! Seu {{produto}} esta disponivel com {{desconto}} de desconto. Aproveite!"
    }
  ]
}

{
  "account": "{{account_id}}",
  "messages": [
    {
      "number": "{{test_number}}"
    }
  ],
  "content": {
