        {
          "type": "openUrl",
          "title": "🛒 Ver Produtos",
          "value": "https://loja.exemplo.com/smartphones"
        },
        {
          "type": "call",
          "title": "📞 Ligar Agora",
          "value": "1140001234"
        },
        {
          "type": "reply",
          "title": "ℹ️ Mais Info",
          "value": "Quero mais informações sobre a promoção"
        }
      ]
    }
  },
  "callback": "https://webhook.site/seu-webhook-aqui"
}

